return [{
  json: {
    subject: 'Manual test: Automation engineer contract',
    from: { text: 'Acme Talent <alerts@acme.example>' },
    date: '2026-04-09T12:00:00.000Z',
    text: 'Remote contract. Need Python, n8n and APIs. Budget USD 2500. https://example.com/jobs/automation-engineer',
    textPlain: 'Remote contract. Need Python, n8n and APIs. Budget USD 2500. https://example.com/jobs/automation-engineer',
    body: 'Remote contract. Need Python, n8n and APIs. Budget USD 2500. https://example.com/jobs/automation-engineer',
    messageId: 'manual-test-email-alerts-001',
    uid: 'manual-test-email-alerts-001',
    id: 'manual-test-email-alerts-001'
  }
}];

const sourceKey = 'email_alerts';
const sourceLabel = 'Alertas por Correo';

const subject = String($json.subject ?? $json.headers?.subject ?? 'Sin asunto').trim() || 'Sin asunto';
const from = String($json.from?.text ?? $json.from ?? $json.headers?.from ?? '').trim();
const dateValue = $json.date ?? $json.internalDate ?? $json.headers?.date ?? null;
const rawBody = [
  $json.text,
  $json.textPlain,
  $json.body,
  $json.html,
].filter(Boolean).join('\n\n').trim();

const urlMatch = rawBody.match(/https?:\/\/[^\s<>"]+/i);
const url = urlMatch ? urlMatch[0].replace(/[)\].,;]+$/, '') : '';
const budgetMatch = rawBody.match(/(?:usd|us\$|\$)\s*([0-9][0-9,]*(?:\.[0-9]+)?)/i);
const budgetValue = budgetMatch ? Number(String(budgetMatch[1]).replace(/,/g, '')) : null;

return [{
  json: {
    source_key: sourceKey,
    source_label: sourceLabel,
    items: [
      {
        external_id: String($json.messageId ?? $json.uid ?? $json.id ?? subject),
        title: subject,
        company: from,
        url,
        raw_text: rawBody || subject,
        posted_at: dateValue ? new Date(dateValue).toISOString() : new Date().toISOString(),
        budget_min: budgetValue,
        budget_max: budgetValue,
        budget_text: budgetValue ? `USD ${budgetValue}` : '',
        currency: 'USD',
        stack: [],
        risk_level: 'low',
        risk_reasons: [],
      },
    ],
  },
}];
